SELECT COUNT(*) AS driver_cancelled_rides
FROM rides
WHERE status = 'cancelled' AND cancellation_reason = 'driver_cancelled';

SELECT AVG(fare) AS average_fare_completed_rides
FROM rides
WHERE status = 'completed';

SELECT COUNT(*) AS rating_count_2026
FROM ratings
WHERE EXTRACT(YEAR FROM rated_at) = 2026;

SELECT COUNT(*) AS tesla_vehicle_count
FROM vehicles
WHERE make = 'Tesla';

SELECT AVG(rating) AS average_rating_2025
FROM ratings
WHERE EXTRACT(YEAR FROM rated_at) = 2025;

SELECT AVG(rating) AS avg_rating_2026
FROM ratings
WHERE EXTRACT(YEAR FROM rated_at) = 2026;

SELECT payment_method, COUNT(*) AS payment_count
FROM payments
GROUP BY payment_method;

SELECT COUNT(*) AS red_vehicle_count
FROM vehicles
WHERE color = 'Red';
